// Finished-draw presentation data. Live balances, claims and writes never use this cache.
import { CHAIN, CONTRACTS } from './chain-config.js';
import { reusableJackpotPayload } from './last-day-state.js';
import { packJackpotCache, unpackJackpotCache } from './jackpot-cache-codec.js';

const MAX_DAYS = 12;
const MAX_PAGES = 4;
const MAX_CHARS = 1_000_000;
let scope = null;
let saved = null;
const serializedDraws = new Map();
const key = () => `degenerus:jackpots:v2:${CHAIN.id}:${CONTRACTS.GAME}:${CHAIN.deployBlock}`.toLowerCase();
const json = value => JSON.stringify(value, (_key, item) => typeof item === 'bigint' ? String(item) : item);
const copy = value => JSON.parse(json(value));

function validDraw(draw, day) {
  if (!Number.isSafeInteger(Number(day)) || Number(day) <= 0
    || !reusableJackpotPayload(draw, day)) return false;
  try {
    const start = BigInt(draw.summary.blockRange.start);
    return start >= BigInt(CHAIN.deployBlock || 0)
      && BigInt(draw.summary.blockRange.end) >= start;
  } catch { return false; }
}

function state() {
  const current = key();
  if (scope === current && saved) return saved;
  scope = current;
  serializedDraws.clear();
  saved = { draws: {}, pages: [] };
  try {
    const data = unpackJackpotCache(JSON.parse(localStorage.getItem(current)));
    if (data && typeof data.draws === 'object' && data.draws && !Array.isArray(data.draws)) {
      for (const [day, record] of Object.entries(data.draws).slice(-MAX_DAYS)) {
        if (validDraw(record?.draw, day)) saved.draws[day] = record;
      }
    }
    if (Array.isArray(data?.pages)) saved.pages = data.pages.filter(page => page?.value?.days?.some?.(validRng)).slice(-MAX_PAGES);
  } catch { /* Corrupt, blocked or missing storage is a cache miss. */ }
  return saved;
}

function validRng(row) {
  try {
    return Number.isSafeInteger(Number(row?.day)) && Number(row.day) > 0
      && BigInt(row.finalWord) > 0n && row.mainTraitsPacked != null
      && (row.bonusTraitDraw === false || row.bonusTraitsPacked != null);
  } catch { return false; }
}

function validPage(value) {
  return Array.isArray(value?.days) && value.days.length > 0 && value.days.every(validRng);
}

function persist() {
  const data = state();
  const days = Object.keys(data.draws).sort((a, b) => data.draws[a].savedAt - data.draws[b].savedAt);
  const evict = () => {
    const day = days.shift();
    delete data.draws[day];
    serializedDraws.delete(day);
  };
  while (days.length > MAX_DAYS) evict();
  const serialize = () => {
    const raw = json(data);
    if (raw.length <= MAX_CHARS) return raw;
    const compact = json(packJackpotCache(JSON.parse(raw)));
    return compact.length < raw.length ? compact : raw;
  };
  let encoded = serialize();
  while (encoded.length > MAX_CHARS && days.length > 1) {
    evict();
    encoded = serialize();
  }
  if (encoded.length > MAX_CHARS) return; // Huge draws remain available in this tab.
  try { localStorage.setItem(scope, encoded); }
  catch { /* A full/private browser still keeps its in-session copy. */ }
}

export function rememberCompletedJackpot(draw) {
  if (!validDraw(draw, draw?.day)) return false;
  const data = state();
  const day = String(draw.day);
  const previous = data.draws[day];
  const encoded = json(draw);
  if (previous && serializedDraws.get(day) === encoded) return true;
  serializedDraws.set(day, encoded);
  // A replacement seal must not inherit ticket matches from the prior result.
  const sameSeal = previous?.draw?.summary?.blockRange?.end === draw.summary.blockRange.end;
  const listedRng = data.pages.flatMap(page => page.value.days).find(row => validRng(row) && Number(row.day) === Number(day));
  const exactRng = validRng(draw.rng) && Number(draw.rng.day) === Number(day) ? draw.rng : null;
  const rng = exactRng && (String(listedRng?.finalWord) !== String(exactRng.finalWord)
    || Number(listedRng?.mainTraitsPacked) !== Number(exactRng.mainTraitsPacked))
    ? exactRng : listedRng ?? exactRng;
  data.draws[day] = { draw: JSON.parse(encoded), savedAt: Date.now(),
    rng: copy(rng ?? (sameSeal ? previous.rng ?? null : null)), players: sameSeal ? previous.players : {} };
  persist();
  return true;
}

export function readCompletedJackpot(day) {
  const draw = state().draws[String(day)]?.draw;
  return validDraw(draw, day) ? copy(draw) : null;
}

export function readLatestCompletedJackpot() {
  const days = Object.keys(state().draws).map(Number).sort((a, b) => b - a);
  for (const day of days) {
    const draw = readCompletedJackpot(day);
    if (draw) return draw;
  }
  return null;
}

export function readCompletedJackpotRng(day) {
  const record = state().draws[String(day)];
  return validDraw(record?.draw, day) && validRng(record?.rng) ? copy(record.rng) : null;
}

export function rememberJackpotResponse(path, value) {
  if (/^\/game\/jackpot\/last-day(?:\?|$)/.test(path)) {
    rememberCompletedJackpot(value);
    return;
  }
  // A pending day must not discard the completed rows next to it. Keep the
  // page for per-day metadata, but only serve wholly complete pages as routes.
  if (!/^\/replay\/rng(?:\?|$)/.test(path) || !Array.isArray(value?.days) || !value.days.some(validRng)) return;
  const data = state();
  data.pages = data.pages.filter(page => page.path !== path);
  data.pages.push({ path, value: copy(value) });
  data.pages = data.pages.slice(-MAX_PAGES);
  for (const row of value.days) {
    if (!validRng(row)) continue;
    const record = data.draws[String(row.day)];
    if (record) record.rng = copy(row);
  }
  persist();
}

export function readSavedJackpotRoute(path, { latestDay = null } = {}) {
  if (/^\/replay\/rng(?:\?|$)/.test(path)) {
    const page = state().pages.find(page => page.path === path)?.value;
    if (!validPage(page)) return null;
    const newest = Math.max(...page.days.map(row => Number(row.day)));
    const historical = new URL(path, 'https://local.invalid').searchParams.has('beforeDay');
    // Mount can precede polling's saved-day restoration. Show a sealed cached
    // draw then; the independent live day probe still discovers newer draws.
    if ((!historical && Number(latestDay) > 0 && newest < Number(latestDay))
      || !validDraw(state().draws[String(newest)]?.draw, newest)) return null;
    return copy(page);
  }
  const match = path.match(/^\/game\/jackpot\/day\/(\d+)\/(summary|winners|roll1|roll2)$/)
    ?? path.match(/^\/replay\/day\/(\d+)$/);
  if (!match) return null;
  const draw = readCompletedJackpot(Number(match[1]));
  if (!draw) return null;
  if (match[2] === 'winners') return { day: draw.day, level: draw.level, winners: draw.winners };
  if (match[2]) return draw[match[2]];
  const row = state().draws[String(draw.day)]?.rng;
  if (!validRng(row) || !draw.winners.every(winner => Array.isArray(winner.breakdown))) return null;
  return { day: draw.day, rng: { rawWord: row.finalWord, finalWord: row.finalWord },
    distributions: draw.winners.flatMap(winner => winner.breakdown) };
}

export function readJackpotTraits(day, player, level, kind = 'main') {
  const record = state().draws[String(day)];
  if (!validDraw(record?.draw, day)) return null;
  const traits = record.players?.[String(player).toLowerCase()]?.[`${kind}:${level}`];
  return Array.isArray(traits) && traits.every(trait => Number.isInteger(trait) && trait >= 0 && trait <= 255)
    ? new Set(traits) : null;
}

export function rememberJackpotTraits(day, player, level, traits, kind = 'main') {
  const record = state().draws[String(day)];
  if (!record || !validDraw(record.draw, day) || !/^0x[0-9a-f]{40}$/i.test(player || '')) return;
  const values = [...traits];
  if (!values.every(trait => Number.isInteger(trait) && trait >= 0 && trait <= 255)) return;
  record.players ??= {};
  const address = player.toLowerCase();
  const entry = record.players[address] ?? {};
  entry[`${kind}:${level}`] = values;
  delete record.players[address];
  record.players[address] = entry;
  while (Object.keys(record.players).length > 4) delete record.players[Object.keys(record.players)[0]];
  persist();
}

export function resetJackpotCacheMemoryForTest() { scope = null; saved = null; serializedDraws.clear(); }
